package hexadecimal

import "errors"

// maxInt64 is the largest value a signed 64-bit integer can hold.
// It is used only to detect overflow; the conversion itself is done
// from first principles below.
const maxInt64 = 1<<63 - 1

// Sentinel errors returned by ParseHex.
var (
	errSyntax = errors.New("syntax error: invalid hexadecimal string")
	errRange  = errors.New("range error: value out of int64 range")
)

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent using first principles. It returns a syntax error for empty
// or non-hexadecimal input and a range error if the value does not fit in
// an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errSyntax
	}

	var result int64
	for i := 0; i < len(in); i++ {
		d, ok := hexValue(in[i])
		if !ok {
			return 0, errSyntax
		}
		// Detect overflow before it happens: result*16 + d overflows
		// int64 exactly when result > (maxInt64 - d) / 16.
		if result > (maxInt64-int64(d))/16 {
			return 0, errRange
		}
		result = result*16 + int64(d)
	}
	return result, nil
}

// HandleErrors runs ParseHex over each input and reports one of "none",
// "syntax", or "range" for each, matching the error produced.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case errors.Is(err, errRange):
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}

// hexValue maps a single hexadecimal character to its numeric value.
// The boolean reports whether the character is a valid hex digit.
func hexValue(c byte) (int, bool) {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0'), true
	case c >= 'a' && c <= 'f':
		return int(c-'a'+10), true
	case c >= 'A' && c <= 'F':
		return int(c-'A'+10), true
	}
	return 0, false
}

